#!/usr/bin/env bash
#
# test-build-traceability.sh — the self-test of scripts/build-traceability.sh.
#
# WHY: a gate that can never turn red is worse than no gate: it gives the
#      impression that every requirement is covered, while it checks nothing.
#      A traceability matrix that is generated by a script is only worth
#      something if the script is able to fail — so every case below proves
#      that the generator turns RED on a broken input, and that it turns green
#      again on the real tree.
#
# WHAT IS PROVEN
#   1. the real tree is green — every requirement has a proof
#   2. a requirement whose test class is deleted turns the generator red
#   3. a device procedure that nobody defined turns the generator red
#   4. a requirement whose proof is removed turns the generator red
#   5. the generated matrix has one row per requirement
#
# HOW THE CASES WORK
#   The generator reads the tree through options, so a case does not have to
#   copy the whole repository: it copies the one input that it breaks and
#   points the generator at the copy.
#
# USAGE
#   ./scripts/test-build-traceability.sh
#
# EXIT CODES
#   0  every case passed
#   1  at least one case failed
#   2  usage error (the generator is missing)
#

set -u

SCRIPT_DIR="$(cd -- "$(dirname -- "$0")" && pwd)"
CHECK_SCRIPT="$SCRIPT_DIR/build-traceability.sh"
REPO_ROOT="$(cd -- "$SCRIPT_DIR/.." && pwd)"

if [ ! -x "$CHECK_SCRIPT" ]; then
  printf 'ERROR: %s is missing or not executable.\n' "$CHECK_SCRIPT" >&2
  exit 2
fi

passed=0
failed=0
workdir=""

cleanup() {
  [ -n "$workdir" ] && rm -rf "$workdir"
  return 0
}
trap cleanup EXIT

ok() {
  passed=$((passed + 1))
  printf '  ok   %s\n' "$1"
}

bad() {
  failed=$((failed + 1))
  printf '  FAIL %s\n' "$1"
}

workdir=$(mktemp -d "${TMPDIR:-/tmp}/phairplay-traceability-test.XXXXXX") || exit 2

printf 'test-build-traceability.sh\n'

# ── 1. the real tree is green ────────────────────────────────────────────────
out=$("$CHECK_SCRIPT" --root "$REPO_ROOT" --out "$workdir/green.md" 2>&1)
if [ $? -eq 0 ]; then
  ok "the real tree passes the generator"
else
  bad "the real tree passes the generator (output: $out)"
fi

# ── 2. a deleted test class turns the generator red ──────────────────────────
rm -rf "$workdir/tests"
cp -R "$REPO_ROOT/app/src/test/kotlin" "$workdir/tests" 2>/dev/null
rm -f "$workdir/tests/com/phairplay/dlna/DlnaImageDecoderTest.kt"
out=$("$CHECK_SCRIPT" --root "$REPO_ROOT" --test-dir "$workdir/tests" --out "$workdir/case2.md" 2>&1)
if printf '%s' "$out" | grep -q "FAILED: traceability" && printf '%s' "$out" | grep -q "FR-64"; then
  ok "a requirement whose test class is deleted turns the generator red"
else
  bad "a requirement whose test class is deleted turns the generator red (output: $out)"
fi

# ── 3. an undefined device procedure turns the generator red ─────────────────
# DT-18 is the only proof of NFR-31 — removing its definition must fail the run
sed 's/DT-18/DT-xx/g' "$REPO_ROOT/docs/spec/DEVICE_PROCEDURES.md" > "$workdir/device-procedures.md" 2>/dev/null
out=$("$CHECK_SCRIPT" --root "$REPO_ROOT" \
  --device-plan "$workdir/device-procedures.md" \
  --device-plan "$REPO_ROOT/docs/guides/DEVICE_TEST_PLAN.md" \
  --device-plan "$REPO_ROOT/docs/spec/ACCEPTANCE_CRITERIA.md" \
  --out "$workdir/case3.md" 2>&1)
if printf '%s' "$out" | grep -q "FAILED: traceability" && \
   printf '%s' "$out" | grep -q "undefined device procedure" && \
   printf '%s' "$out" | grep -q "NFR-31"; then
  ok "a device procedure that nobody defined turns the generator red"
else
  bad "a device procedure that nobody defined turns the generator red (output: $out)"
fi

# ── 4. a requirement without any proof turns the generator red ───────────────
sed 's/^- FR-62:.*/- FR-62: A failed advertisement MUST be retried with a bounded backoff and MUST end in an explicit error state./' \
  "$REPO_ROOT/docs/spec/REQUIREMENTS.md" > "$workdir/requirements.md"
grep -v '^| FR-62 |' "$REPO_ROOT/docs/spec/REQUIREMENTS_MATRIX.md" > "$workdir/matrix.md"
out=$("$CHECK_SCRIPT" --root "$REPO_ROOT" \
  --requirements "$workdir/requirements.md" --matrix "$workdir/matrix.md" \
  --out "$workdir/case4.md" 2>&1)
if printf '%s' "$out" | grep -q "FAILED: traceability" && printf '%s' "$out" | grep -q "FR-62"; then
  ok "a requirement without any proof turns the generator red"
else
  bad "a requirement without any proof turns the generator red (output: $out)"
fi

# ── 5. the generated matrix has one row per requirement ──────────────────────
expected=$(grep -cE '^- (FR|NFR)-[0-9]+:' "$REPO_ROOT/docs/spec/REQUIREMENTS.md")
actual=$(grep -cE '^\| (FR|NFR)-[0-9]+ \|' "$workdir/green.md" 2>/dev/null || echo 0)
if [ "$expected" = "$actual" ] && [ "$expected" -gt 0 ]; then
  ok "the generated matrix has one row per requirement ($expected rows)"
else
  bad "the generated matrix has one row per requirement (expected $expected, got $actual)"
fi

printf '\n%s\n' "----------------------------------------"
printf 'passed: %s   failed: %s\n' "$passed" "$failed"

if [ "$failed" -ne 0 ]; then
  printf 'RESULT: the traceability generator is not trustworthy.\n'
  exit 1
fi

printf 'RESULT: every case passed.\n'
exit 0
